`timescale 1ns/1ps
// =============================================================
// vhfastmulb16_addf32_rne_lat4_rand_tb.v
// Random/directed regression for vhfastmulb16_addf32_rne_lat4.
//
// Vectors are generated by scripts/gen_addf32_vectors.py into
// build/vhfastmulb16_addf32_rne_lat4_rand.hex
// (one 96-bit word per line):
//   [95:64] = FP32 A
//   [63:32] = FP32 B
//   [31:0]  = expected FP32 sum (RNE)
//
// The stream test uses LAT = 4 and checks pair k-LAT on cycle k.
// Also checks en=0 HOLD and reset priority.
// =============================================================

module vhfastmulb16_addf32_rne_lat4_rand_tb;

    localparam integer N         = 4096;  // must match generator --count
    localparam integer LAT       = 4;
    localparam integer MAX_PRINT = 20;
    localparam integer VEC_FILE_LINES = N;

    reg         clk;
    reg         reset;
    reg         en;
    reg  [31:0] inf32a;
    reg  [31:0] inf32b;
    wire [31:0] outf32c;

    vhfastmulb16_addf32_rne_lat4 uut (
        .clk     (clk),
        .reset   (reset),
        .en      (en),
        .inf32a  (inf32a),
        .inf32b  (inf32b),
        .outf32c (outf32c)
    );

    reg [95:0] vec [0:N-1];

    integer k;
    integer checked;
    integer errors;
    reg [31:0] hold_val;

    task check(input integer idx);
        reg [31:0] va;
        reg [31:0] vb;
        reg [31:0] ve;
        begin
            va = vec[idx][95:64];
            vb = vec[idx][63:32];
            ve = vec[idx][31:0];
            checked = checked + 1;
            if (outf32c !== ve) begin
                errors = errors + 1;
                if (errors <= MAX_PRINT) begin
                    $display("[ERROR] t=%0t | pair %0d | a=%h b=%h",
                             $time, idx, va, vb);
                    $display("        exp: outf32c=%h | got: outf32c=%h", ve, outf32c);
                end
            end
        end
    endtask

    // ---------------- Clock generation 100 MHz ----------------
    initial begin
        clk = 1'b0;
        forever #5 clk = ~clk;
    end

    // ---------------- RESET: 5 clk ----------------
    initial begin
        reset  = 1'b1;
        en     = 1'b0;
        inf32a = 32'h0000_0000;
        inf32b = 32'h0000_0000;
        repeat (5) @(negedge clk);
        reset = 1'b0;
    end

    // ---------------- Main scenario ----------------
    initial begin
        $dumpfile("build/vhfastmulb16_addf32_rne_lat4_rand.vcd");
        $dumpvars(0, vhfastmulb16_addf32_rne_lat4_rand_tb);

        $readmemh("build/vhfastmulb16_addf32_rne_lat4_rand.hex", vec, 0, VEC_FILE_LINES - 1);

        checked = 0;
        errors  = 0;

        // Wait for reset release + 10 clocks.
        @(negedge reset);
        repeat (10) @(negedge clk);

        if (outf32c !== 32'h0000_0000) begin
            errors = errors + 1;
            $display("[ERROR] t=%0t | after reset: exp outf32c=00000000, got outf32c=%h",
                     $time, outf32c);
        end

        // Stream N pairs, one per clock. Result of pair k appears on k+4.
        for (k = 0; k < N + LAT; k = k + 1) begin
            @(posedge clk); #1;

            if (k < N) begin
                inf32a = vec[k][95:64];
                inf32b = vec[k][63:32];
                en     = 1'b1;
            end else begin
                en = 1'b0;
            end

            if (k >= LAT)
                check(k - LAT);
        end

        // ---- en=0 HOLD ----
        en     = 1'b0;
        inf32a = 32'h7FC0_0000;
        inf32b = 32'h3F80_0000;
        @(posedge clk); #1;
        hold_val = outf32c;
        repeat (6) @(posedge clk); #1;
        if (outf32c !== hold_val) begin
            errors = errors + 1;
            $display("[ERROR] t=%0t | en=0 hold: exp outf32c=%h, got outf32c=%h",
                     $time, hold_val, outf32c);
        end

        // ---- reset priority over en ----
        en     = 1'b1;
        reset  = 1'b1;
        @(posedge clk); #1;
        if (outf32c !== 32'h0000_0000) begin
            errors = errors + 1;
            $display("[ERROR] t=%0t | reset priority: exp outf32c=00000000, got outf32c=%h",
                     $time, outf32c);
        end
        reset = 1'b0;
        en    = 1'b0;

        repeat (10) @(posedge clk);

        $display("---------------------------------------------");
        $display("Checked vectors: %0d", checked);
        $display("Errors:          %0d", errors);
        if (errors == 0)
            $display("TEST PASSED");
        else
            $display("TEST FAILED");
        $display("---------------------------------------------");
        $finish;
    end

    // ---------------- Watchdog ----------------
    initial begin
        #10000000;
        $display("[ERROR] Testbench timeout!");
        $finish;
    end

endmodule
